import Foundation

/// A word partnership learners should memorise as a unit, e.g. "make a decision".
/// Generated by `Tools/build_collocations.py`; `example2` comes from Open English WordNet.
public struct Collocation: Decodable, Identifiable, Hashable, Sendable {
    public let phrase: String
    public let group: String
    public let example: String
    public let example2: String?
    /// A common learner error for this collocation, e.g. "do a mistake".
    public let wrong: String?

    public var id: String { phrase }
}

public enum CollocationCatalog {
    public static let all: [Collocation] = {
        guard let url = Bundle.module.url(forResource: "Collocations", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let items = try? JSONDecoder().decode([Collocation].self, from: data) else { return [] }
        return items
    }()

    /// Group names in file order ("make", "do", ..., "noun phrases").
    public static let groups: [String] = all.reduce(into: []) { if !$0.contains($1.group) { $0.append($1.group) } }
}
